select 'songs.tono_original' as columna, (select pg_get_constraintdef(oid) from pg_constraint where conname = 'songs_tono_original_formato' and conrelid = 'public.songs'::regclass) as restriccion, (select convalidated::text from pg_constraint where conname = 'songs_tono_original_formato' and conrelid = 'public.songs'::regclass) as validada, (select count(*)::text from public.songs where tono_original !~ '^([A-G][#b]?m?)?$') as filas_que_no_cumplen
union all select 'service_blocks.tono', (select pg_get_constraintdef(oid) from pg_constraint where conname = 'service_blocks_tono_formato' and conrelid = 'public.service_blocks'::regclass), (select convalidated::text from pg_constraint where conname = 'service_blocks_tono_formato' and conrelid = 'public.service_blocks'::regclass), (select count(*)::text from public.service_blocks where tono !~ '^([A-G][#b]?m?)?$')
